import os
import sqlite3
from datetime import datetime
from flask import Flask, request, render_template_string, redirect, url_for, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DB_PATH = "db.sqlite3"

# HTML template for the forum interface
INDEX_HTML = """
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>MyForum</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; }
        .message { border: 1px solid #ddd; padding: 1rem; margin-bottom: 1rem; border-radius: 8px; background: #f9f9f9; }
        .username { font-weight: bold; color: #333; margin-bottom: 0.5rem; display: block; }
        .content { color: #555; }
        .form-group { margin-bottom: 1rem; }
        input, textarea, button { width: 100%; padding: 0.5rem; box-sizing: border-box; margin-bottom: 0.5rem; }
        button { background: #007bff; color: white; border: none; cursor: pointer; }
        button:hover { background: #0056b3; }
        .error { color: red; background: #ffe6e6; padding: 0.5rem; border-radius: 4px; margin-bottom: 1rem; }
    </style>
</head>
<body>
    <h1>MyForum</h1>
    <div class="form-group">
        <textarea id="msgContent" placeholder="What's on your mind?"></textarea>
        <input id="msgUsername" placeholder="Username" value="Anonymous">
        <button onclick="postMessage()">Post</button>
    </div>
    <div id="messages">
        {{ messages|safe }}
    </div>

    <script>
        async function loadMessages() {
            const resp = await fetch('?limit=20&offset={{ offset }}&sort={{ sort }}');
            const data = await resp.text();
            document.getElementById('messages').innerHTML = data;
        }

        async function postMessage() {
            const content = document.getElementById('msgContent').value;
            const username = document.getElementById('msgUsername').value || 'Anonymous';
            if (!content.trim()) return;

            await fetch('/messages', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ content, username })
            });
            document.getElementById('msgContent').value = '';
            loadMessages();
        }

        // Initial load
        loadMessages();
    </script>
</body>
</html>
"""

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        content TEXT NOT NULL,
        created_at TEXT NOT NULL
    )''')
    conn.commit()
    conn.close()

init_db()

@app.route('/messages', methods=['GET', 'POST'])
def messages():
    if request.method == 'POST':
        data = request.get_json(silent=True) or request.form
        content = data.get('content', '').strip()
        username = data.get('username', 'Anonymous').strip()

        if not content:
            return jsonify({'error': 'Content is required'}), 400

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        ts = datetime.utcnow().isoformat()
        c.execute('INSERT INTO messages (username, content, created_at) VALUES (?, ?, ?)',
                  (username, content, ts))
        conn.commit()
        conn.close()
        return jsonify({'status': 'ok'}), 200

    # GET request
    limit = int(request.args.get('limit', 10))
    offset = int(request.args.get('offset', 0))
    sort = request.args.get('sort', 'desc').upper()

    if sort not in ('ASC', 'DESC'):
        sort = 'DESC'

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    order = 'ASC' if sort == 'ASC' else 'DESC'
    c.execute('SELECT username, content, created_at FROM messages ORDER BY created_at ? LIMIT ? OFFSET ?',
              (order, limit, offset))
    rows = c.fetchall()
    conn.close()

    # Generate HTML for messages
    messages_html = ""
    for username, content, created_at in rows:
        messages_html += f'<div class="message"><span class="username">{username}</span><div class="content">{content}</div></div>'

    if not messages_html:
        messages_html = '<p>No messages yet.</p>'

    # Render template with pagination info
    render_html = INDEX_HTML.replace('{{ messages|safe }}', messages_html)
    render_html = render_html.replace('{{ offset }}', str(offset))
    render_html = render_html.replace('{{ sort }}', sort)
    return render_html, 200, {'Content-Type': 'text/html; charset=utf-8'}

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
